export function getExportsForResource(resource: string): ExportDef[] {
  return exportsCatalog.filter((item) => item.resource === resource)
}

export function findExport(resource: string, name: string): ExportDef | undefined {
  return exportsCatalog.find((item) => item.resource === resource && item.name === name)
}
